<template><section v-if="product" class="grid gap-10 md:grid-cols-2"><div><div class="aspect-square overflow-hidden rounded-3xl bg-slate-100"><img v-if="product.imageUrl" :src="product.imageUrl" class="h-full w-full object-cover"/></div><div class="mt-4 flex flex-wrap gap-2"><span v-for="(a,i) in optionGroups" :key="i" class="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold">{{a.attribute.name}}</span></div></div><div class="py-2"><span class="font-bold text-indigo-600">PRODUCT</span><h1 class="mt-3 text-4xl font-black">{{product.name}}</h1><p class="mt-3 text-slate-500">{{product.brand?.name}} · {{product.category?.name}}</p><p class="mt-5 text-3xl font-black">{{Number(selectedVariant?.price||product.price).toLocaleString()}} {{product.currency||'ETB'}}</p><p class="mt-5 leading-7 text-slate-600">{{product.description}}</p><div v-for="group in optionGroups" :key="group.attribute.id" class="mt-7"><p class="font-bold">{{group.attribute.name}}</p><div class="mt-2 flex flex-wrap gap-2"><button v-for="v in group.values" :key="v.id" @click="select(group.attribute.id,v.id)" :class="['rounded-xl border px-4 py-2 text-sm font-bold',selected[group.attribute.id]===v.id?'border-indigo-600 bg-indigo-50 text-indigo-700':'bg-white']">{{v.label||v.value}}</button></div></div><p v-if="selectedVariant" class="mt-6 text-sm font-semibold text-emerald-600">Available stock: {{availableStock}}</p><button :disabled="!selectedVariant||availableStock<1" @click="add" class="mt-8 w-full rounded-xl bg-indigo-600 px-6 py-3 font-bold text-white disabled:opacity-40">Add selected variant to cart</button></div></section><div v-else class="py-20 text-center">Loading product…</div></template>
<script>
import api from '../services/api'
import {addToCart} from '../stores'
export default{data(){return{product:null,selected:{},error:''}},computed:{optionGroups(){const m={};(this.product?.variants||[]).forEach(v=>(v.options||[]).forEach(o=>{m[o.attributeId]??={attribute:o.attribute,values:[]};if(!m[o.attributeId].values.find(x=>x.id===o.attributeValueId))m[o.attributeId].values.push(o.value)}));return Object.values(m)},selectedVariant(){return (this.product?.variants||[]).find(v=>(v.options||[]).every(o=>this.selected[o.attributeId]===o.attributeValueId))||((this.product?.variants||[]).length===1?this.product.variants[0]:null)},availableStock(){return (this.selectedVariant?.inventory||[]).reduce((n,x)=>n+Number(x.quantityOnHand)-Number(x.reservedQuantity),0)}},async mounted(){try{this.product=(await api.get('/products/'+this.$route.params.slug)).data.data;if(this.optionGroups.length===0&&this.product.variants?.length===1)this.selectedVariant&&this.product.variants.forEach(v=>(v.options||[]).forEach(o=>this.selected[o.attributeId]=o.attributeValueId))}catch{this.product=null}},methods:{select(a,v){this.selected[a]=v},add(){if(addToCart(this.product,this.selectedVariant))this.$router.push('/cart')}}}
</script>